REPLACE INTO `acore_string` (`entry`, `content_default`, `locale_frFR`) VALUES (21023,"Welcome to Rochenoire", "Bienvenue sur Rochenoire");
REPLACE INTO `acore_string` (`entry`, `content_default`, `locale_frFR`) VALUES (21024,"Welcome to Rochenoire, a scaled Wrath of the Lich King server.\r\n\r\nScaling is a game mechanic introduced in WoW® Legion.\r\n\r\nThe essence of this feature is that item drops and rewards, mobs, and quests scale to the level of the character.\r\n\r\nLeveling zones from 10 to 80 will dynamically scale to your character’s level for a certain range.\r\n\r\nThis also affects quests, dungeons, and zones.\r\n\r\nBenjaminLSR, <Core Developer>", "Bienvenue sur Rochenoire, un serveur Wrath of the Lich King mis à l'échelle.\r\nLa mise à l'échelle est un mécanisme de jeu introduit dans WoW® Legion.\r\nL'essence de cette fonctionnalité est que les objets récupérés, les récompenses, les monstres et les quêtes sont mis à l'échelle en fonction du niveau du personnage. \r\nLes zones de niveau de 10 à 80 s'adapteront dynamiquement au niveau de votre personnage dans une certaine plage.\r\nCela affecte également les quêtes, les donjons et les zones.\r\nBenjaminLSR, <Développeur principal>"); 
REPLACE INTO `acore_string` (`entry`, `content_default`, `locale_frFR`) VALUES (21019,"Congratulations $N on reaching level 10 !\r\n\r\nNow we shall see if you have what it takes to turn the tides of this battle.\r\nGet ready to explore the world of Azeroth and seek out what treasures it holds for you.\r\n\r\nFor the Horde!\r\n\r\nThrall, <Warchief of the Horde>", "Félicitations $N d\'avoir atteint le niveau 10!\r\n\r\nMaintenant, nous verrons si vous avez ce qu\'il faut pour renverser le cours de cette bataille.\r\nPréparez vous à explorer le monde d\'Azeroth et à découvrir les trésors qu\'il vous réserve.\r\n\r\nPour la horde!\r\n\r\nThrall, <Chef de guerre de la Horde>");
REPLACE INTO `acore_string` (`entry`, `content_default`, `locale_frFR`) VALUES (21020,"The city of Stormwind thanks you for your service, $N.\r\n\r\nNow that you have reached level 10, prepare yourself to travel the realm in search of threats to the citizens of this great land.\r\nI leave the task of stomping out the evil that is encroaching upon us in your hands.\r\n\r\nFor the Alliance!\r\n\r\nKing Varian Wrynn <King of Stormwind>", "La cité de Stormwind vous remercie pour votre service, $N.\r\n\r\nMaintenant que vous avez atteint le niveau 10, préparez vous à voyager dans le royaume et mettre fin aux menaces pour nos citoyens.\r\nJe compte sur vous pour faire taire ce mal qui nous envahit.\r\n\r\nPour l\'Alliance!\r\n\r\nRoi Varian Wrynn <Roi de Hurlevent>");
REPLACE INTO `acore_string` (`entry`, `content_default`, `locale_frFR`) VALUES (21021,"Note from your Warchief", "Une note de votre chef de guerre");
REPLACE INTO `acore_string` (`entry`, `content_default`, `locale_frFR`) VALUES (21022,"Note from your Regent", "Une note de votre régent");
